mapper.update:
UPDATE market_reminder SET status = #{to}, updated_at = #{now}
, sent_at = #{now}
, cancel_via = #{cancelVia}
WHERE id = #{id} AND status = #{from}

mapper.select:
SELECT r.id FROM market_reminder r JOIN market_question m ON m.id = r.market_id
WHERE r.status = 'ACTIVE' AND m.open_at <= #{now}
ORDER BY r.id LIMIT #{limit}
